{
  "name": "loadline-website",
  "private": true,
  "version": "0.1.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "tsc -b && vite build",
    "preview": "vite preview",
    "lint": "tsc -b --noEmit"
  },
  "dependencies": {
    "react": "^19.0.0",
    "react-dom": "^19.0.0"
  },
  "devDependencies": {
    "@tailwindcss/vite": "^4.0.0",
    "@types/react": "^19.0.0",
    "@types/react-dom": "^19.0.0",
    "@vitejs/plugin-react": "^4.3.4",
    "tailwindcss": "^4.0.0",
    "typescript": "~5.7.2",
    "vite": "^6.0.3"
  }
}

import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";
import tailwindcss from "@tailwindcss/vite";

export default defineConfig({
  plugins: [react(), tailwindcss()],
});

{
  "compilerOptions": {
    "target": "ES2022",
    "lib": ["ES2023"],
    "module": "ESNext",
    "skipLibCheck": true,
    "moduleResolution": "bundler"
  },
  "include": ["vite.config.ts"]
}

{
  "buildCommand": "npm run build",
  "outputDirectory": "dist",
  "framework": "vite",
  "rewrites": [{ "source": "/(.*)", "destination": "/index.html" }]
}

:root {
  --page: #f5f4ef;
  --surface: #fbfaf7;
  --surface-raised: #ffffff;
  --ink: #171a17;
  --muted: #686d65;
  --line: rgba(23, 26, 23, 0.12);

  --hero: #0e110f;
  --hero-raised: #151a17;
  --hero-line: rgba(242, 245, 234, 0.12);
  --hero-copy: #f4f4eb;
  --hero-muted: #a5ada1;

  --signal: #c7f17b;
  --signal-ink: #151a11;
  --finding: #ff8b77;
  --hypothesis: #b6a4f4;
  --projected: #8cb9e8;

  --radius-sm: 10px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-xl: 32px;
  --content-width: 1220px;

  --font-sans: "Inter", system-ui, -apple-system, sans-serif;
  --font-mono: "Geist Mono", ui-monospace, monospace;
  --font-serif: "Instrument Serif", Georgia, serif;

  --nav-height: 72px;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/** All graph/report values are illustrative sample UI — not live measurements. */

export const REPO_URL = "https://github.com/aarush323/NeatHacks";

export const QUICKSTART = `git clone https://github.com/aarush323/NeatHacks.git
cd NeatHacks
uv sync
cp .env.example .env
# Set LOADLINE_MODEL and your provider API key in .env
uv run loadline doctor
uv run loadline run --repo /absolute/path/to/your/repo`;

export type GraphNode = {
  id: string;
  label: string;
  kind: "operation" | "route" | "service" | "query" | "dependency";
  source?: string;
  evidenceLabel: "illustrative runtime observation" | "static code relationship" | "hypothesis";
  detail: string;
  x: number;
  y: number;
};

export type GraphEdge = {
  from: string;
  to: string;
  kind: "static-relationship" | "runtime-observation" | "hypothesis";
};

export const SAMPLE_NODES: GraphNode[] = [
  {
    id: "op",
    label: "GET /widgets/{id}",
    kind: "operation",
    evidenceLabel: "illustrative runtime observation",
    detail: "p95 climbs as offered load increases (sample curve).",
    x: 48,
    y: 28,
  },
  {
    id: "route",
    label: "main.py:70",
    kind: "route",
    source: "app/main.py",
    evidenceLabel: "static code relationship",
    detail: "Route handler; holds DB session across downstream call in buggy path.",
    x: 168,
    y: 72,
  },
  {
    id: "svc",
    label: "order_service",
    kind: "service",
    source: "app/service.py",
    evidenceLabel: "static code relationship",
    detail: "Service layer between route and data access.",
    x: 288,
    y: 116,
  },
  {
    id: "query",
    label: "queries.py:48",
    kind: "query",
    source: "app/queries.py",
    evidenceLabel: "hypothesis",
    detail: "Possible contention under pool saturation — hypothesis only.",
    x: 408,
    y: 72,
  },
  {
    id: "db",
    label: "PostgreSQL pool",
    kind: "dependency",
    evidenceLabel: "illustrative runtime observation",
    detail: "Bounded pool; latency pins near timeout under load (sample).",
    x: 528,
    y: 28,
  },
];

export const SAMPLE_EDGES: GraphEdge[] = [
  { from: "op", to: "route", kind: "runtime-observation" },
  { from: "route", to: "svc", kind: "static-relationship" },
  { from: "svc", to: "query", kind: "static-relationship" },
  { from: "query", to: "db", kind: "hypothesis" },
];

export const SPARKLINE = [12, 18, 24, 38, 52, 71, 89, 112, 98, 76, 54, 41];

export const FAQ = [
  {
    q: "Does Loadline run against production?",
    a: "No. It boots a supported target locally in Docker/Compose for an isolated investigation run. Point it at a repo you can run on your machine—not a live production service.",
  },
  {
    q: "Does it modify my application?",
    a: "Loadline stores runs and reports under $LOADLINE_HOME (default ~/.local/share/loadline). It does not rewrite your app source. Optional .loadline.yaml hints in the target repo are under your control.",
  },
  {
    q: "Does every repo work?",
    a: "No. You need a bootable HTTP app and a supported Compose or Dockerfile path. A clear blocker is a valid outcome.",
  },
  {
    q: "What does the agent actually do?",
    a: "Three tools today: search the repo (Entire Graph when available), read files in the target repo, and run short k6 experiments. It does not freely edit your codebase.",
  },
  {
    q: "What do I need?",
    a: "Git, Docker + Compose v2, Python 3.12, uv, and an LLM provider key for loadline run. Neatlogs tracing is optional.",
  },
  {
    q: "Where is the report?",
    a: "$LOADLINE_HOME/runs/<run_id>/report.md — use loadline report show <RUN_DIR> to print it.",
  },
  {
    q: "Is it fully secure?",
    a: "No complete security boundary. Compose boot applies sandbox policy (no published ports, internal network, resource caps). Dockerfile-only paths differ. Inspect any target before running.",
  },
  {
    q: "Is there a hosted SaaS or PyPI package?",
    a: "Not yet. Loadline is a local CLI you install from this repository. loadline dashboard --serve is a read-only local run browser on port 8123—not this site.",
  },
] as const;

@import "tailwindcss";
@import "./styles/tokens.css";
@import "./styles/landing.css";

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  background: var(--page);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

.section-pad {
  padding: clamp(3.25rem, 8vw, 8.25rem) clamp(1rem, 4vw, 2rem);
}

.content {
  max-width: var(--content-width);
  margin: 0 auto;
}

.hero-veil {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 70% 20%, rgba(199, 241, 123, 0.08), transparent 55%),
    radial-gradient(ellipse 50% 40% at 20% 80%, rgba(182, 164, 244, 0.06), transparent 50%),
    linear-gradient(180deg, #0e110f 0%, #121614 45%, #0a0c0b 100%);
  pointer-events: none;
}

.hero-veil::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 2px,
    rgba(255, 255, 255, 0.015) 2px,
    rgba(255, 255, 255, 0.015) 3px
  );
  opacity: 0.4;
}

@media (prefers-reduced-motion: no-preference) {
  .hero-veil {
    animation: veil-drift 24s ease-in-out infinite alternate;
  }
}

@keyframes veil-drift {
  from {
    filter: hue-rotate(0deg);
  }
  to {
    filter: hue-rotate(8deg);
  }
}

.spotlight-card {
  position: relative;
  overflow: hidden;
  background: var(--surface-raised);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
}

.spotlight-card::before {
  content: "";
  position: absolute;
  inset: 0;
  opacity: 0;
  background: radial-gradient(
    600px circle at var(--spot-x, 50%) var(--spot-y, 50%),
    rgba(199, 241, 123, 0.12),
    transparent 40%
  );
  transition: opacity 0.2s ease;
  pointer-events: none;
}

@media (hover: hover) and (prefers-reduced-motion: no-preference) {
  .spotlight-card:hover::before {
    opacity: 1;
  }
}

.blur-in {
  animation: blur-in 0.7s ease forwards;
}

@keyframes blur-in {
  from {
    opacity: 0;
    filter: blur(8px);
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    filter: blur(0);
    transform: translateY(0);
  }
}

.reveal {
  opacity: 0;
  transform: translateY(16px);
  transition:
    opacity 0.5s ease,
    transform 0.5s ease;
}

.reveal.visible {
  opacity: 1;
  transform: none;
}

@media (prefers-reduced-motion: reduce) {
  .reveal {
    opacity: 1;
    transform: none;
  }
}

import { useEffect, useRef, useState } from "react";

export function useReveal<T extends HTMLElement>() {
  const ref = useRef<T | null>(null);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if (reduced) {
      setVisible(true);
      return;
    }
    const io = new IntersectionObserver(
      ([entry]) => {
        if (entry?.isIntersecting) {
          setVisible(true);
          io.disconnect();
        }
      },
      { threshold: 0.12, rootMargin: "0px 0px -40px 0px" },
    );
    io.observe(el);
    return () => io.disconnect();
  }, []);

  return { ref, visible };
}

type Props = { variant?: "light" | "dark"; showWord?: boolean };

export function BrandMark({ variant = "dark", showWord = true }: Props) {
  const stroke = variant === "light" ? "var(--signal)" : "var(--signal)";
  const text = variant === "light" ? "var(--hero-copy)" : "var(--ink)";
  return (
    <a href="#" className="inline-flex items-center gap-2.5 no-underline" aria-label="Loadline home">
      <svg width="32" height="32" viewBox="0 0 32 32" aria-hidden="true">
        <rect width="32" height="32" rx="8" fill={variant === "light" ? "#151A17" : "#0E110F"} />
        <path
          d="M4 22 L10 22 L14 10 L18 18 L22 14 L28 14"
          fill="none"
          stroke={stroke}
          strokeWidth="2.2"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
      {showWord && (
        <span className="text-lg font-semibold tracking-tight" style={{ color: text }}>
          Loadline
        </span>
      )}
    </a>
  );
}

import { useState } from "react";

type Props = { code: string; label?: string };

export function CopyCodeButton({ code, label = "Copy commands" }: Props) {
  const [state, setState] = useState<"idle" | "ok" | "fail">("idle");

  async function copy() {
    try {
      await navigator.clipboard.writeText(code);
      setState("ok");
      setTimeout(() => setState("idle"), 2000);
    } catch {
      setState("fail");
      setTimeout(() => setState("idle"), 2500);
    }
  }

  const msg = state === "ok" ? "Copied to clipboard" : state === "fail" ? "Copy failed" : "";

  return (
    <div className="flex flex-wrap items-center gap-3">
      <button
        type="button"
        onClick={copy}
        className="rounded-full px-4 py-2 text-sm font-medium transition-colors"
        style={{ background: "var(--signal)", color: "var(--signal-ink)" }}
      >
        {label}
      </button>
      <span className="text-sm text-[var(--muted)]" role="status" aria-live="polite">
        {msg}
      </span>
    </div>
  );
}

import { useEffect, useState } from "react";
import { BrandMark } from "./BrandMark";
import { REPO_URL } from "../data/copy";

const LINKS = [
  { href: "#how", label: "How it works" },
  { href: "#finds", label: "What it finds" },
  { href: "#quickstart", label: "Quickstart" },
  { href: "#safety", label: "Safety" },
];

export function SiteNav() {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 24);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  const navClass = scrolled
    ? "border-b border-[var(--hero-line)] bg-[rgba(14,17,15,0.85)] backdrop-blur-md"
    : "border-b border-transparent bg-transparent";

  return (
    <header
      className={`fixed top-0 z-50 w-full transition-colors duration-200 ${navClass}`}
      style={{ height: "var(--nav-height)" }}
    >
      <div className="content flex h-full items-center justify-between gap-4 px-4 md:px-8">
        <BrandMark variant="light" />
        <nav className="hidden items-center gap-8 md:flex" aria-label="Primary">
          {LINKS.map((l) => (
            <a
              key={l.href}
              href={l.href}
              className="text-sm text-[var(--hero-muted)] transition-colors hover:text-[var(--hero-copy)]"
            >
              {l.label}
            </a>
          ))}
          <a
            href={REPO_URL}
            target="_blank"
            rel="noreferrer"
            className="text-sm text-[var(--hero-muted)] hover:text-[var(--hero-copy)]"
          >
            Source
          </a>
          <a
            href="#quickstart"
            className="rounded-full px-4 py-2 text-sm font-medium"
            style={{ background: "var(--signal)", color: "var(--signal-ink)" }}
          >
            Run it on your repo
          </a>
        </nav>
        <button
          type="button"
          className="md:hidden rounded-lg border border-[var(--hero-line)] px-3 py-2 text-sm text-[var(--hero-copy)]"
          aria-expanded={open}
          aria-controls="mobile-nav"
          onClick={() => setOpen((v) => !v)}
        >
          Menu
        </button>
      </div>
      {open && (
        <div
          id="mobile-nav"
          className="border-t border-[var(--hero-line)] bg-[var(--hero)] px-4 py-4 md:hidden"
        >
          <ul className="flex flex-col gap-3">
            {LINKS.map((l) => (
              <li key={l.href}>
                <a
                  href={l.href}
                  className="block py-2 text-[var(--hero-copy)]"
                  onClick={() => setOpen(false)}
                >
                  {l.label}
                </a>
              </li>
            ))}
            <li>
              <a href={REPO_URL} target="_blank" rel="noreferrer" className="block py-2 text-[var(--hero-muted)]">
                Source
              </a>
            </li>
          </ul>
        </div>
      )}
    </header>
  );
}

import { useMemo, useState } from "react";
import { SAMPLE_EDGES, SAMPLE_NODES, SPARKLINE, type GraphNode } from "../data/copy";

type Filter = "all" | "pressure";

export function PressureGraphHero() {
  const [selected, setSelected] = useState<string>("op");
  const [filter, setFilter] = useState<Filter>("all");

  const node = SAMPLE_NODES.find((n) => n.id === selected) ?? SAMPLE_NODES[0];

  const edges = useMemo(() => {
    if (filter === "all") return SAMPLE_EDGES;
    return SAMPLE_EDGES.filter((e) => e.kind === "runtime-observation" || e.from === "op" || e.to === "op");
  }, [filter]);

  const pathD = useMemo(() => {
    const w = 560;
    const h = 80;
    const max = Math.max(...SPARKLINE);
    const pts = SPARKLINE.map((v, i) => {
      const x = (i / (SPARKLINE.length - 1)) * w;
      const y = h - (v / max) * (h - 8) - 4;
      return `${x},${y}`;
    });
    return `M ${pts.join(" L ")}`;
  }, []);

  return (
    <div
      className="relative overflow-hidden rounded-[var(--radius-lg)] border border-[var(--hero-line)] bg-[var(--hero-raised)] p-4 md:p-5"
      role="region"
      aria-label="Illustrative investigation graph"
    >
      <div className="mb-3 flex flex-wrap items-center justify-between gap-2 text-[10px] uppercase tracking-[0.14em] text-[var(--hero-muted)]">
        <span>Illustrative investigation · sample data</span>
        <div className="flex gap-2">
          {(["all", "pressure"] as const).map((f) => (
            <button
              key={f}
              type="button"
              onClick={() => setFilter(f)}
              className={`rounded-full px-2.5 py-1 text-[10px] transition-colors ${
                filter === f ? "bg-[var(--signal)] text-[var(--signal-ink)]" : "border border-[var(--hero-line)]"
              }`}
            >
              {f === "all" ? "All relationships" : "Pressure path"}
            </button>
          ))}
        </div>
      </div>

      <div className="mb-4 rounded-[var(--radius-sm)] border border-[var(--hero-line)] bg-[#0a0d0b] p-3">
        <div className="mb-1 flex justify-between text-[11px] text-[var(--hero-muted)]">
          <span>p95 latency (sample)</span>
          <span>offered load →</span>
        </div>
        <svg viewBox="0 0 560 80" className="h-16 w-full" aria-hidden="true">
          <path d={pathD} fill="none" stroke="var(--signal)" strokeWidth="2" />
          <path
            d={`${pathD} L 560 80 L 0 80 Z`}
            fill="url(#spark)"
            opacity="0.15"
          />
          <defs>
            <linearGradient id="spark" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="var(--signal)" />
              <stop offset="100%" stopColor="transparent" />
            </linearGradient>
          </defs>
        </svg>
      </div>

      <div className="hidden md:block">
        <svg viewBox="0 0 580 150" className="w-full" role="img" aria-label="Code relationship graph sample">
          {edges.map((e) => {
            const a = SAMPLE_NODES.find((n) => n.id === e.from)!;
            const b = SAMPLE_NODES.find((n) => n.id === e.to)!;
            const stroke =
              e.kind === "runtime-observation"
                ? "var(--signal)"
                : e.kind === "hypothesis"
                  ? "var(--hypothesis)"
                  : "rgba(244,244,235,0.35)";
            const dash = e.kind === "hypothesis" ? "6 4" : undefined;
            return (
              <line
                key={`${e.from}-${e.to}`}
                x1={a.x}
                y1={a.y}
                x2={b.x}
                y2={b.y}
                stroke={stroke}
                strokeWidth={e.kind === "runtime-observation" ? 2.5 : 1.5}
                strokeDasharray={dash}
              />
            );
          })}
          {SAMPLE_NODES.map((n) => (
            <NodeButton key={n.id} node={n} active={selected === n.id} onSelect={() => setSelected(n.id)} />
          ))}
        </svg>
      </div>

      <ol className="md:hidden space-y-2 text-sm text-[var(--hero-copy)]">
        {SAMPLE_NODES.map((n) => (
          <li key={n.id}>
            <button
              type="button"
              className={`w-full rounded-lg border px-3 py-2 text-left ${
                selected === n.id ? "border-[var(--signal)]" : "border-[var(--hero-line)]"
              }`}
              onClick={() => setSelected(n.id)}
            >
              {n.label}
            </button>
          </li>
        ))}
      </ol>

      <Inspector node={node} />
      <p className="mt-3 text-[11px] text-[var(--hero-muted)]">
        LOAD → OBSERVE → INSPECT → REPORT · Not a live stream
      </p>
    </div>
  );
}

function NodeButton({
  node,
  active,
  onSelect,
}: {
  node: GraphNode;
  active: boolean;
  onSelect: () => void;
}) {
  return (
    <g>
      <circle
        cx={node.x}
        cy={node.y}
        r={active ? 14 : 11}
        fill={active ? "var(--signal)" : "#1c221e"}
        stroke={active ? "var(--signal)" : "var(--hero-line)"}
        strokeWidth={2}
        className="cursor-pointer"
        onClick={onSelect}
        onKeyDown={(e) => e.key === "Enter" && onSelect()}
        tabIndex={0}
        role="button"
        aria-label={node.label}
      />
      <text
        x={node.x}
        y={node.y - 18}
        textAnchor="middle"
        fill="var(--hero-muted)"
        fontSize="9"
        fontFamily="var(--font-mono)"
      >
        {node.label.length > 18 ? `${node.label.slice(0, 16)}…` : node.label}
      </text>
    </g>
  );
}

function Inspector({ node }: { node: GraphNode }) {
  return (
    <div className="mt-4 rounded-[var(--radius-sm)] border border-[var(--hero-line)] bg-[#0a0d0b] p-3 text-sm">
      <div className="font-mono text-[var(--signal)]">{node.label}</div>
      <div className="mt-1 text-[var(--hero-muted)]">{node.evidenceLabel}</div>
      <p className="mt-2 text-[var(--hero-copy)] leading-relaxed">{node.detail}</p>
      {node.source && (
        <p className="mt-2 font-mono text-xs text-[var(--hero-muted)]">{node.source}</p>
      )}
    </div>
  );
}

const STACK = [
  { name: "Docker", note: null },
  { name: "k6", note: null },
  { name: "Entire Graph", note: null },
  { name: "Pydantic AI", note: null },
  { name: "Neatlogs", note: "optional tracing" },
];

export function TechRail() {
  return (
    <section className="border-y border-[var(--line)] bg-[var(--surface)] py-10">
      <div className="content px-4 md:px-8">
        <p className="mb-6 text-center text-sm font-medium text-[var(--muted)]">
          A real investigation loop. Not another dashboard.
        </p>
        <ul className="flex flex-wrap items-center justify-center gap-x-10 gap-y-4">
          {STACK.map((t) => (
            <li key={t.name} className="flex flex-col items-center gap-1">
              <span className="text-sm font-semibold tracking-wide text-[var(--ink)]">{t.name}</span>
              {t.note && (
                <span className="text-[10px] uppercase tracking-wider text-[var(--muted)]">{t.note}</span>
              )}
            </li>
          ))}
        </ul>
      </div>
    </section>
  );
}

import { useReveal } from "../hooks/useReveal";

const STEPS = [
  {
    n: "01",
    title: "Point at a repo",
    body: "Loadline reads supported HTTP service structure and Docker/Compose configuration from the target you choose—not every repo qualifies.",
    icon: "repo",
  },
  {
    n: "02",
