import { useEffect, useMemo, useState } from "react";
import {
  PRESSURE_PATH_IDS,
  SAMPLE_EDGES,
  SAMPLE_NODES,
  SPARKLINE,
  type GraphEdge,
  type GraphNode,
} from "../data/copy";
import { useReducedMotion } from "../hooks/useReducedMotion";

type Filter = "all" | "pressure";

const CHART_W = 560;
const CHART_H = 88;

export function PressureGraphHero() {
  const reduced = useReducedMotion();
  const [selected, setSelected] = useState("op");
  const [filter, setFilter] = useState<Filter>("all");
  const [chartIdx, setChartIdx] = useState(8);
  const [chartReady, setChartReady] = useState(false);

  useEffect(() => {
    if (!reduced) setChartReady(true);
    else setChartReady(true);
  }, [reduced]);

  const node = SAMPLE_NODES.find((n) => n.id === selected) ?? SAMPLE_NODES[0];

  const visibleEdges = useMemo(() => {
    const base =
      filter === "pressure"
        ? SAMPLE_EDGES.filter(
            (e) =>
              PRESSURE_PATH_IDS.includes(e.from) &&
              PRESSURE_PATH_IDS.includes(e.to) &&
              PRESSURE_PATH_IDS.indexOf(e.to) === PRESSURE_PATH_IDS.indexOf(e.from) + 1,
          )
        : SAMPLE_EDGES;
    return base;
  }, [filter]);

  const pathD = useMemo(() => buildChartPath(SPARKLINE), []);
  const chartPoints = useMemo(() => buildChartPoints(SPARKLINE), []);

  const highlightedIds = useMemo(() => {
    const n = SAMPLE_NODES.find((nd) => chartIdx >= nd.chartBand) ?? SAMPLE_NODES[0];
    const idx = PRESSURE_PATH_IDS.indexOf(n.id);
    return new Set(PRESSURE_PATH_IDS.slice(0, idx + 1));
  }, [chartIdx]);

  function selectFromChart(i: number) {
    setChartIdx(i);
    const match =
      [...SAMPLE_NODES].reverse().find((nd) => i >= nd.chartBand) ?? SAMPLE_NODES[0];
    setSelected(match.id);
  }

  return (
    <div
      className="instrument-panel p-4 md:p-6"
      role="region"
      aria-label="Illustrative pressure investigation graphic"
    >
      <div className="mb-4 flex flex-wrap items-center justify-between gap-2 font-mono text-[10px] uppercase tracking-[0.16em] text-[var(--telemetry)]">
        <span>Illustrative investigation · sample data</span>
        <div className="flex gap-2">
          {(["all", "pressure"] as const).map((f) => (
            <button
              key={f}
              type="button"
              onClick={() => setFilter(f)}
              className={`rounded px-2.5 py-1 transition-colors ${
                filter === f
                  ? "bg-[var(--signal)] text-[var(--signal-ink)]"
                  : "border border-[var(--hero-line)] text-[var(--hero-muted)]"
              }`}
            >
              {f === "all" ? "All relationships" : "Pressure path"}
            </button>
          ))}
        </div>
      </div>

      <div className="mb-5 rounded-[var(--radius-sm)] border border-[var(--hero-line)] bg-[#060807] p-3">
        <div className="mb-2 flex justify-between font-mono text-[10px] text-[var(--hero-muted)]">
          <span>p95 latency · sample</span>
          <span>offered load →</span>
        </div>
        <svg viewBox={`0 0 ${CHART_W} ${CHART_H}`} className="h-[5.5rem] w-full" role="img" aria-label="Sample latency curve">
          <path
            d={`${pathD} L ${CHART_W} ${CHART_H} L 0 ${CHART_H} Z`}
            fill="url(#sparkFill)"
            opacity="0.12"
          />
          <path
            d={pathD}
            fill="none"
            stroke="var(--signal)"
            strokeWidth="2"
            className={chartReady && !reduced ? "chart-draw animate" : ""}
            pathLength={1200}
          />
          <defs>
            <linearGradient id="sparkFill" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="var(--signal)" />
              <stop offset="100%" stopColor="transparent" />
            </linearGradient>
          </defs>
          {chartPoints.map((pt, i) => (
            <circle
              key={i}
              cx={pt.x}
              cy={pt.y}
              r={chartIdx === i ? 5 : 3}
              fill={chartIdx === i ? "var(--signal)" : "var(--hero-muted)"}
              className="cursor-pointer"
              role="button"
              tabIndex={0}
              aria-label={`Sample load point ${i + 1}`}
              onClick={() => selectFromChart(i)}
              onKeyDown={(e) => e.key === "Enter" && selectFromChart(i)}
            />
          ))}
        </svg>
      </div>

      <div className="hidden md:block">
        <svg viewBox="0 0 580 160" className="w-full" role="img" aria-label="Code relationship graph sample">
          {visibleEdges.map((e) => (
            <GraphEdgeLine
              key={`${e.from}-${e.to}`}
              edge={e}
              dimmed={
                filter === "pressure" &&
                (!highlightedIds.has(e.from) || !highlightedIds.has(e.to))
              }
              animate={!reduced && highlightedIds.has(e.from) && highlightedIds.has(e.to)}
            />
          ))}
          {SAMPLE_NODES.map((n) => (
            <NodeGlyph
              key={n.id}
              node={n}
              active={selected === n.id}
              onPath={highlightedIds.has(n.id)}
              onSelect={() => setSelected(n.id)}
            />
          ))}
        </svg>
      </div>

      <ol className="space-y-2 md:hidden">
        {SAMPLE_NODES.map((n) => (
          <li key={n.id}>
            <button
              type="button"
              className={`w-full rounded-lg border px-3 py-2 text-left font-mono text-sm ${
                selected === n.id ? "border-[var(--signal)] text-[var(--signal)]" : "border-[var(--hero-line)]"
              }`}
              onClick={() => setSelected(n.id)}
            >
              {n.label}
            </button>
          </li>
        ))}
      </ol>

      <Inspector node={node} />

      <div className="mt-4 flex flex-wrap gap-4 font-mono text-[10px] text-[var(--hero-muted)]">
        <Legend swatch="var(--signal)" label="Measured (sample)" />
        <Legend swatch="rgba(242,240,232,0.4)" label="Static relationship" />
        <Legend swatch="var(--hypothesis)" label="Hypothesis" dashed />
      </div>
    </div>
  );
}

function buildChartPath(values: number[]) {
  const max = Math.max(...values);
  const pts = values.map((v, i) => {
    const x = (i / (values.length - 1)) * CHART_W;
    const y = CHART_H - (v / max) * (CHART_H - 10) - 5;
    return `${x},${y}`;
  });
  return `M ${pts.join(" L ")}`;
}

function buildChartPoints(values: number[]) {
  const max = Math.max(...values);
  return values.map((v, i) => ({
    x: (i / (values.length - 1)) * CHART_W,
    y: CHART_H - (v / max) * (CHART_H - 10) - 5,
  }));
}

function GraphEdgeLine({
  edge,
  dimmed,
  animate,
}: {
  edge: GraphEdge;
  dimmed: boolean;
  animate: boolean;
}) {
  const a = SAMPLE_NODES.find((n) => n.id === edge.from)!;
  const b = SAMPLE_NODES.find((n) => n.id === edge.to)!;
  const stroke =
    edge.kind === "runtime-observation"
      ? "var(--signal)"
      : edge.kind === "hypothesis"
        ? "var(--hypothesis)"
        : "rgba(242,240,232,0.35)";
  const isSignal = edge.kind === "runtime-observation" || (animate && edge.kind !== "hypothesis");
  return (
    <line
      x1={a.x}
      y1={a.y}
      x2={b.x}
      y2={b.y}
      stroke={stroke}
      strokeWidth={edge.kind === "runtime-observation" ? 2.5 : 1.5}
      strokeDasharray={edge.kind === "hypothesis" ? "6 4" : undefined}
      opacity={dimmed ? 0.2 : 1}
      className={isSignal && animate ? "signal-path signal-path-animated" : undefined}
    />
  );
}

function NodeGlyph({
  node,
  active,
  onPath,
  onSelect,
}: {
  node: GraphNode;
  active: boolean;
  onPath: boolean;
  onSelect: () => void;
}) {
  return (
    <g>
      <circle
        cx={node.x}
        cy={node.y}
        r={active ? 15 : 11}
        fill={active ? "var(--signal)" : onPath ? "#1a2218" : "#121816"}
        stroke={active || onPath ? "var(--signal)" : "var(--hero-line)"}
        strokeWidth={active ? 2.5 : 1.5}
        className="cursor-pointer"
        onClick={onSelect}
        onKeyDown={(e) => e.key === "Enter" && onSelect()}
        tabIndex={0}
        role="button"
        aria-label={node.label}
      />
      <text
        x={node.x}
        y={node.y - 20}
        textAnchor="middle"
        fill="var(--hero-muted)"
        fontSize="9"
        fontFamily="var(--font-mono)"
      >
        {node.label.length > 20 ? `${node.label.slice(0, 18)}…` : node.label}
      </text>
    </g>
  );
}

function Inspector({ node }: { node: GraphNode }) {
  return (
    <div
      className="mt-4 rounded-[var(--radius-sm)] border border-[var(--hero-line)] bg-[#060807] p-4 text-sm transition-opacity duration-200"
      aria-live="polite"
    >
      <div className="flex flex-wrap items-center gap-2">
        <span className="font-mono text-[var(--signal)]">{node.label}</span>
        <span className="rounded border border-[var(--hero-line)] px-1.5 py-0.5 font-mono text-[10px] text-[var(--telemetry)]">
          {node.kind}
        </span>
      </div>
      <p className="mt-2 font-mono text-[10px] text-[var(--hypothesis)]">{node.evidenceDisplay}</p>
      <p className="mt-1 font-mono text-[10px] text-[var(--hero-muted)]">{node.relationship}</p>
      <p className="mt-2 leading-relaxed text-[var(--hero-copy)]">{node.detail}</p>
      {node.source && <p className="mt-2 font-mono text-xs text-[var(--telemetry)]">{node.source}</p>}
    </div>
  );
}

function Legend({ swatch, label, dashed }: { swatch: string; label: string; dashed?: boolean }) {
  return (
    <span className="inline-flex items-center gap-1.5">
      <span
        className="inline-block h-0.5 w-4"
        style={{
          background: dashed ? "transparent" : swatch,
          borderBottom: dashed ? `2px dashed ${swatch}` : undefined,
        }}
      />
      {label}
    </span>
  );
}

