function highlightReport(raw: string) {
  return raw.split("\n").map((line, i) => {
    let content = line;
    if (line.startsWith("# ")) {
      return (
        <span key={i} className="md-h1 block">
          {line}
          {"\n"}
        </span>
      );
    }
    if (line.includes("[MEASURED]")) content = line.replace("[MEASURED]", "⟦MEASURED⟧");
    if (line.includes("[STATIC]")) content = line.replace("[STATIC]", "⟦STATIC⟧");
    if (line.includes("[HYPOTHESIS]")) content = line.replace("[HYPOTHESIS]", "⟦HYPOTHESIS⟧");
    const parts = content.split(/(⟦MEASURED⟧|⟦STATIC⟧|⟦HYPOTHESIS⟧|\*\*[^*]+\*\*)/g);
    return (
      <span key={i} className="block">
        {parts.map((p, j) => {
          if (p === "⟦MEASURED⟧") return <span key={j} className="md-tag text-[var(--signal)]">[MEASURED]</span>;
          if (p === "⟦STATIC⟧") return <span key={j} className="md-tag text-[var(--hero-muted)]">[STATIC]</span>;
          if (p === "⟦HYPOTHESIS⟧") return <span key={j} className="md-tag text-[var(--hypothesis)]">[HYPOTHESIS]</span>;
          if (p.startsWith("**") && p.endsWith("**")) return <span key={j} className="md-strong">{p.slice(2, -2)}</span>;
          return <span key={j}>{p}</span>;
        })}
        {"\n"}
      </span>
    );
  });
}

