/** Seeded lane schematic calibrated to the recorded widget sweep. */

export function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Discrete pool: 5 servers, service time uniform between the recorded
 * downstream bounds (0.3s–0.8s). Waits past the pool timeout shatter.
 */
export function simulate(offeredRps, seed = 7) {
  const pool = 5;
  const timeout = 5;
  const duration = 20;
  const rng = mulberry32(seed + Math.round(offeredRps * 10));
  const freeAt = Array(pool).fill(0);
  let t = 0;
  let next = 0;
  let dropped = 0;
  let arrivals = 0;
  const latencies = [];
  const step = 1 / offeredRps;
  while (t < duration) {
    while (next <= t + 1e-9 && next < duration) {
      arrivals += 1;
      let idx = 0;
      for (let i = 1; i < pool; i += 1) if (freeAt[i] < freeAt[idx]) idx = i;
      const wait = Math.max(0, freeAt[idx] - next);
      if (wait >= timeout) {
        dropped += 1;
      } else {
        const service = 0.3 + rng() * 0.5;
        const done = next + wait + service;
        freeAt[idx] = done;
        latencies.push((wait + service) * 1000);
      }
      next += step;
    }
    t += 0.05;
  }
  latencies.sort((a, b) => a - b);
  const p50 = latencies.length ? latencies[Math.floor(latencies.length * 0.5)] : 0;
  return { arrivals, dropped, p50, queue: dropped > 0 || offeredRps * 0.55 > pool };
}

export function frame(offeredRps) {
  const capacity = 5 / 0.55;
  const busy = Math.max(1, Math.min(5, Math.ceil(offeredRps * 0.55)));
  const queue = Math.max(0, Math.round(offeredRps - capacity));
  const shedding = offeredRps >= 12;
  const instrumentLimit = offeredRps >= 10;
  return { busy, queue, shedding, instrumentLimit, capacity };
}

export function assertCalibrated(waves) {
  const errors = [];
  for (const wave of waves) {
    const op = wave.ops[0];
    const sim = simulate(op.offered_rps);
    const view = frame(op.offered_rps);
    if (op.dropped === 0 && (sim.dropped > op.count * 0.05 || view.queue > 0)) {
      errors.push(`low rate ${op.offered_rps} shed or queued`);
    }
    if (op.dropped > 30 && sim.dropped === 0 && !view.shedding) {
      errors.push(`high rate ${op.offered_rps} did not shed`);
    }
    if (op.vus_max >= op.vu_ceiling && !view.instrumentLimit) {
      errors.push(`missing instrument limit at ${op.offered_rps}`);
    }
    if (op.offered_rps <= 5 && view.instrumentLimit) {
      errors.push(`false instrument limit at ${op.offered_rps}`);
    }
    if (op.offered_rps <= 5 && (sim.p50 < 250 || sim.p50 > 1200)) {
      errors.push(`p50 ${sim.p50} outside tolerance of recorded low-rate latency`);
    }
  }
  const p95s = waves.map((w) => w.ops[0].p95_ms);
  for (let i = 1; i < p95s.length; i += 1) {
    if (p95s[i] + 50 < p95s[i - 1] && waves[i].ops[0].offered_rps > waves[i - 1].ops[0].offered_rps) {
      errors.push("recorded p95 fell while offered rate rose");
    }
  }
  return errors;
}

