  Group,
  IcosahedronGeometry,
  Mesh,
  MeshBasicMaterial,
  PerspectiveCamera,
  PlaneGeometry,
  Points,
  PointsMaterial,
  Scene,
  ShaderMaterial,
  SRGBColorSpace,
  TorusGeometry,
  WebGLRenderer,
  DoubleSide,
} from "three";
import type { Tier } from "../lib/tier";
import { lookup, nearestOp, p95At } from "../lib/sample";

export type WorldHandle = {
  setRps: (rps: number) => void;
  setPaused: (paused: boolean) => void;
  dispose: () => void;
};

const maxRps = Number(lookup("waves.3.ops.0.offered_rps"));
const maxP = p95At(maxRps);
const prediction = Number(lookup("prediction.capacity_rps"));

function ridge(rps: number) {
  return (p95At(Math.max(0, Math.min(maxRps, rps))) / maxP) * 2.55;
}

function xOf(rps: number) {
  return -6 + (rps / maxRps) * 12;
}

export function mountWorld(
  canvas: HTMLCanvasElement,
  tier: Tier,
  onLost: () => void,
): WorldHandle {
  const renderer = new WebGLRenderer({ canvas, antialias: tier === 2, alpha: false, powerPreference: "high-performance" });
  renderer.setClearColor(0x070908, 1);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, tier === 2 ? 1.75 : 1.15));

  const scene = new Scene();
  scene.fog = new Fog(0x070908, 9, 18);
  const camera = new PerspectiveCamera(30, 1, 0.1, 40);
  camera.position.set(0.4, 3.1, 8.4);

  const terrainGeo = new PlaneGeometry(12, 8, tier === 2 ? 140 : 70, tier === 2 ? 80 : 40);
  terrainGeo.rotateX(-Math.PI / 2);
  const pos = terrainGeo.attributes.position;
  for (let i = 0; i < pos.count; i += 1) {
    const x = pos.getX(i);
    const z = pos.getZ(i);
    const rps = ((x + 6) / 12) * maxRps;
    const falloff = Math.exp(-Math.abs(z) * 0.42);
    pos.setY(i, ridge(rps) * falloff);
  }
  terrainGeo.computeVertexNormals();

  const terrain = new Mesh(
    terrainGeo,
    new ShaderMaterial({
      toneMapped: false,
      uniforms: {},
      vertexShader: `
        varying float vH;
        void main() {
          vH = position.y;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        varying float vH;
        void main() {
          float bands = vH * 11.0;
          float fw = max(fwidth(bands), 0.0008);
          float f = abs(fract(bands) - 0.5);
          float edge = min(f, 1.0 - f);
          float line = 1.0 - smoothstep(fw * 0.35, fw * 1.6, edge);
          vec3 lo = vec3(0.025, 0.032, 0.028);
          vec3 hi = vec3(0.07, 0.09, 0.07);
          vec3 col = mix(lo, hi, clamp(vH / 2.4, 0.0, 1.0));
          col = mix(col, vec3(0.78, 1.0, 0.44), line * 0.92);
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    }),
  );
  scene.add(terrain);

  const boulder = new Mesh(
    new IcosahedronGeometry(0.46, 3),
    new ShaderMaterial({
      toneMapped: false,
      uniforms: { uTime: { value: 0 } },
      vertexShader: `
        varying vec3 vN;
        varying vec3 vP;
        void main() {
          vN = normalize(normalMatrix * normal);
          vP = position;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        varying vec3 vN;
        varying vec3 vP;
        vec2 hash(vec2 p) {
          p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));
          return fract(sin(p) * 43758.5453);
        }
        void main() {
          vec2 p = vP.xy * 3.4;
          vec2 n = floor(p);
          float md = 8.0;
          for (int j = -1; j <= 1; j++) {
            for (int i = -1; i <= 1; i++) {
              vec2 g = n + vec2(float(i), float(j));
              vec2 o = hash(g);
              float d = length(g + o - p);
              md = min(md, d);
            }
          }
          float crack = smoothstep(0.08, 0.02, md);
          float pulse = 0.5 + 0.5 * sin(md * 28.0 - uTime * 1.6);
          vec3 rock = vec3(0.16, 0.17, 0.14);
          vec3 edge = vec3(0.78, 1.0, 0.5);
          vec3 col = mix(rock, edge, crack * (0.45 + 0.55 * pulse));
          col += vec3(0.08, 0.1, 0.06) * clamp(vN.y, 0.0, 1.0);
          gl_FragColor = vec4(col, 1.0);
        }
      `,
    }),
  );

  const ring = new Mesh(
    new TorusGeometry(0.72, 0.015, 8, 48),
    new MeshBasicMaterial({ color: new Color("#c7ff70"), toneMapped: false }),
  );
  ring.rotation.x = Math.PI / 2;

  const figure = new Mesh(
    new PlaneGeometry(0.85, 1.7),
    new MeshBasicMaterial({ map: figureTexture(), transparent: true, depthWrite: false, toneMapped: false, side: DoubleSide }),
  );
  const rim = new Mesh(
    new PlaneGeometry(0.9, 1.76),
    new MeshBasicMaterial({ color: new Color("#d6ff6a"), transparent: true, opacity: 0.22, depthWrite: false, toneMapped: false, side: DoubleSide }),
  );

  const marker = new Mesh(
    new PlaneGeometry(0.03, 1.4),
    new MeshBasicMaterial({ color: new Color("#b6a4f4"), transparent: true, opacity: 0.85, toneMapped: false, side: DoubleSide }),
  );
  marker.position.set(xOf(prediction), ridge(prediction) + 0.7, 0.15);

  const actor = new Group();
  actor.add(boulder, ring, figure, rim);
  scene.add(actor);
  scene.add(marker);

  const debrisCount = tier === 2 ? 80 : 24;
  const debrisGeo = new BufferGeometry();
  debrisGeo.setAttribute("position", new Float32BufferAttribute(new Float32Array(debrisCount * 3), 3));
  const debris = new Points(
    debrisGeo,
    new PointsMaterial({ color: new Color("#ffb199"), size: 0.045, transparent: true, opacity: 0.0, depthWrite: false }),
  );
  scene.add(debris);

  let rps = Number(lookup("waves.1.ops.0.offered_rps"));
  let paused = false;
  let raf = 0;
  let lost = false;

  function place() {
    const y = ridge(rps);
    actor.position.set(xOf(rps), y + 0.55, 0.2);
    const scale = 0.72 + (rps / maxRps) * 0.7;
    boulder.scale.setScalar(scale);
    const op = nearestOp(rps);
    const occ = op.vus_max / op.vu_ceiling;
    ring.scale.setScalar(0.85 + occ * 0.45);
    (ring.material as MeshBasicMaterial).color.set(occ >= 0.9 ? "#7ee7ff" : "#c7ff70");
    figure.position.set(-0.95, 0.15, 0.05);
    rim.position.set(-0.95, 0.15, -0.02);
    const lean = Math.min(0.45, rps / maxRps);
    figure.rotation.z = -lean;
    rim.rotation.z = -lean;
    (rim.material as MeshBasicMaterial).opacity = 0.12 + lean * 0.4;
    const shed = rps >= Number(lookup("waves.2.ops.0.offered_rps"));
    (debris.material as PointsMaterial).opacity = shed ? 0.85 : 0;
  }

  function resize() {
    const w = canvas.clientWidth || 1;
    const h = canvas.clientHeight || 1;
    camera.aspect = w / h;
    camera.updateProjectionMatrix();
    renderer.setSize(w, h, false);
  }

  const ro = new ResizeObserver(resize);
  ro.observe(canvas);
  resize();
  place();

  const onContextLost = (event: Event) => {
    event.preventDefault();
    lost = true;
    cancelAnimationFrame(raf);
    onLost();
  };
  canvas.addEventListener("webglcontextlost", onContextLost);

  const clockStart = performance.now();
  const loop = (now: number) => {
    raf = requestAnimationFrame(loop);
    if (paused || document.hidden || lost) return;
    const t = (now - clockStart) / 1000;
    const mat = boulder.material as ShaderMaterial;
    mat.uniforms.uTime.value = tier === 1 ? 0 : t;
    if (tier === 2) boulder.rotation.y += 0.004 + rps / maxRps * 0.01;
    if ((debris.material as PointsMaterial).opacity > 0) {
      const arr = debrisGeo.attributes.position as Float32BufferAttribute;
      for (let i = 0; i < debrisCount; i += 1) {
        const behind = xOf(rps) - 0.2 - ((i * 17 + t * 18) % 2.4);
        arr.setXYZ(i, behind, ridge(Math.max(0, rps - i * 0.05)) * 0.3 + ((i * 13) % 10) / 40, ((i % 7) - 3) * 0.12);
      }
      arr.needsUpdate = true;
    }
    camera.lookAt(xOf(rps) * 0.25, 0.7, 0);
    renderer.render(scene, camera);
  };
  raf = requestAnimationFrame(loop);

  return {
    setRps(next) {
      rps = next;
      place();
    },
    setPaused(next) {
      paused = next;
    },
    dispose() {
      cancelAnimationFrame(raf);
      ro.disconnect();
      canvas.removeEventListener("webglcontextlost", onContextLost);
      renderer.dispose();
      terrainGeo.dispose();
      (terrain.material as ShaderMaterial).dispose();
      boulder.geometry.dispose();
      (boulder.material as ShaderMaterial).dispose();
    },
  };
}

function figureTexture() {
  const c = document.createElement("canvas");
  c.width = 256;
  c.height = 512;
  const g = c.getContext("2d");
  if (!g) return new CanvasTexture(c);
  g.clearRect(0, 0, 256, 512);
  g.strokeStyle = "#f4f0e4";
  g.lineWidth = 7;
  g.lineCap = "round";
  g.lineJoin = "round";
  g.beginPath();
  g.arc(128, 78, 26, 0, Math.PI * 2);
  g.moveTo(128, 108);
  g.lineTo(156, 250);
  g.moveTo(150, 160);
  g.lineTo(196, 214);
  g.moveTo(146, 175);
  g.lineTo(92, 214);
  g.moveTo(156, 250);
  g.lineTo(196, 410);
  g.moveTo(156, 250);
  g.lineTo(112, 400);
  g.stroke();
  const tex = new CanvasTexture(c);
  tex.colorSpace = SRGBColorSpace;
  return tex;
}

import { lookup, p95At } from "../lib/sample";
import { useRun } from "../state/run";

/** Static composition. This is the page when WebGL, motion, or the GPU is unavailable. */
export function WorldPoster() {
  const { rps } = useRun();
  const maxRps = Number(lookup("waves.3.ops.0.offered_rps"));
  const maxP = p95At(maxRps);
  const ridge = (steps = 56) => {
    let d = "";
    for (let i = 0; i <= steps; i += 1) {
      const t = i / steps;
      const x = 60 + t * 1120;
      const y = 560 - (p95At(t * maxRps) / maxP) * 400;
      d += i === 0 ? `M ${x.toFixed(1)} ${y.toFixed(1)}` : ` L ${x.toFixed(1)} ${y.toFixed(1)}`;
    }
    return d;
  };
  const bx = 60 + (rps / maxRps) * 1120;
  const by = 560 - (p95At(rps) / maxP) * 400;
  const pred = Number(lookup("prediction.capacity_rps"));
  const px = 60 + (pred / maxRps) * 1120;
  const py = 560 - (p95At(pred) / maxP) * 400;

  return (
    <svg className="poster" viewBox="0 0 1240 700" role="img" aria-label="Latency curve drawn as a ridge. A boulder sits on the slope.">
      <defs>
        <radialGradient id="glow" cx="70%" cy="40%" r="50%">
          <stop offset="0%" stopColor="#c7ff70" stopOpacity="0.16" />
          <stop offset="100%" stopColor="#070908" stopOpacity="0" />
        </radialGradient>
        <pattern id="hatch" width="6" height="6" patternUnits="userSpaceOnUse">
          <path d="M0 6 L6 0" stroke="#8a9188" strokeWidth="0.6" />
        </pattern>
      </defs>
      <rect width="1240" height="700" fill="#070908" />
      <rect width="1240" height="700" fill="url(#glow)" />
      {[0, 18, 36, 54, 78].map((offset) => (
        <path key={offset} d={ridge()} transform={`translate(0 ${offset})`} fill="none" stroke="#c7ff70" strokeOpacity={0.18 + (offset === 0 ? 0.7 : 0)} strokeWidth={offset === 0 ? 2.4 : 1} />
      ))}
      <path d={`${ridge()} L 1180 640 L 60 640 Z`} fill="#c7ff70" opacity="0.05" />
      <line x1={px} y1={py} x2={px} y2={py - 70} stroke="#b6a4f4" strokeDasharray="3 4" />
      <circle cx={px} cy={py} r="4" fill="#b6a4f4" />
      <g transform={`translate(${bx} ${by})`}>
        <circle r="34" fill="#141814" stroke="#c7ff70" strokeWidth="1.4" />
        <path d="M-20 -4 L-6 -16 L8 -2 L18 -12" fill="none" stroke="#d6ff6a" strokeWidth="1.2" />
        <path d="M-14 10 L2 4 L16 14" fill="none" stroke="#9aa392" strokeWidth="1" />
      </g>
      <g transform={`translate(${bx - 78} ${by - 20})`} fill="none" stroke="#f2f0e8" strokeWidth="2" strokeLinecap="round">
        <circle cx="0" cy="-46" r="7" />
        <path d="M0 -38 L8 0 L22 -8 M6 -10 L-8 -4 M8 0 L18 36 M8 0 L-2 34" />
      </g>
      <rect x="40" y="40" width="22" height="22" fill="none" stroke="#c7ff70" opacity="0.45" />
    </svg>
  );
}

import { useEffect, useRef, useState } from "react";
import { detectTier, type Tier } from "../lib/tier";
import { useRun } from "../state/run";
import type { WorldHandle } from "../scene/world";

export function WorldCanvas() {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const handleRef = useRef<WorldHandle | null>(null);
  const { rps } = useRun();
  const [tier, setTier] = useState<Tier>(0);
  const [live, setLive] = useState(false);

  useEffect(() => {
    setTier(detectTier());
  }, []);

  useEffect(() => {
    if (tier === 0 || !canvasRef.current) return;
    let dead = false;
    const canvas = canvasRef.current;
    void import("../scene/world").then(({ mountWorld }) => {
      if (dead) return;
      const handle = mountWorld(canvas, tier, () => setLive(false));
      handleRef.current = handle;
      handle.setRps(rps);
      setLive(true);
    });
    return () => {
      dead = true;
      handleRef.current?.dispose();
      handleRef.current = null;
    };
    // mount once per tier; rps is pushed below
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tier]);

  useEffect(() => {
    handleRef.current?.setRps(rps);
  }, [rps]);

  useEffect(() => {
    const node = canvasRef.current;
    if (!node) return;
    const io = new IntersectionObserver(([entry]) => {
      handleRef.current?.setPaused(!entry?.isIntersecting);
    });
    io.observe(node);
    const onHide = () => handleRef.current?.setPaused(document.hidden);
    document.addEventListener("visibilitychange", onHide);
    return () => {
      io.disconnect();
      document.removeEventListener("visibilitychange", onHide);
    };
  }, [tier]);

  if (tier === 0) return null;

  return (
    <canvas
      ref={canvasRef}
      className={`world-canvas${live ? " is-live" : ""}`}
      aria-hidden="true"
    />
  );
}

import { useEffect, useState } from "react";
import { Datum } from "./Datum";
import { frame } from "../lib/laneModel.mjs";
import { lookup, nearestOp, ops, p95At } from "../lib/sample";
import { useRun } from "../state/run";

const PRESETS = [
  { id: "low", label: "Low", src: "waves.0.ops.0.offered_rps" },
  { id: "knee", label: "Knee", src: "waves.1.ops.0.offered_rps" },
  { id: "over", label: "Overload", src: "waves.3.ops.0.offered_rps" },
] as const;

export function PressureInstrument() {
  const { rps, setRps } = useRun();
  const [playing, setPlaying] = useState(false);
  const min = Number(lookup("waves.0.ops.0.offered_rps"));
  const max = Number(lookup("waves.3.ops.0.offered_rps"));
  const view = frame(rps);
  const op = nearestOp(rps);
  const reduced = useReduced();

  useEffect(() => {
    if (!playing || reduced) return;
    const rates = ops().map((item) => item.offered_rps);
    let i = 0;
    const id = window.setInterval(() => {
      i = (i + 1) % rates.length;
      setRps(rates[i]);
    }, 1400);
    return () => window.clearInterval(id);
  }, [playing, reduced, setRps]);

  function onKey(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === "Home") {
      event.preventDefault();
      setRps(min);
    }
    if (event.key === "End") {
      event.preventDefault();
      setRps(max);
    }
  }

  return (
    <section id="instrument" className="instrument" aria-labelledby="instrument-title">
      <div className="content instrument-grid">
        <header>
          <p className="eyebrow">Lane model calibrated to the recorded run</p>
          <h2 id="instrument-title">The hill is the curve.</h2>
          <p className="lede">
            Offered rate moves the boulder. Height is p95. Particles stand for rate, not single requests.
            The ring turns cyan and reads instrument limit when virtual users hit the ceiling.
          </p>
          <p className="formula">
            capacity ≈ pool / hold = <Datum src="code.pool_size" /> / <Datum src="code.hold_s" /> s ≈{" "}
            <Datum src="prediction.capacity_rps" /> rps
          </p>
        </header>

        <div className="readouts" aria-live="polite">
          <Readout k="Offered" v={<Datum src={srcFor(op, "offered_rps")} />} u="rps" />
          <Readout k="p95" v={<Datum src={srcFor(op, "p95_ms")} />} u="ms" />
          <Readout k="p50" v={<Datum src={srcFor(op, "p50_ms")} />} u="ms" />
          <Readout k="Dropped" v={<Datum src={srcFor(op, "dropped")} />} u="iters" />
          <Readout
            k="VUs"
            v={
              <>
                <Datum src={srcFor(op, "vus_max")} /> / <Datum src={srcFor(op, "vu_ceiling")} />
              </>
            }
            u={view.instrumentLimit ? "instrument limit" : "occupancy"}
          />
        </div>

        <div className="controls">
          <label className="slider-label" htmlFor="rps">
            Offered rps
          </label>
          <input
            id="rps"
            type="range"
            min={min}
            max={max}
            step={1}
            value={rps}
            onChange={(e) => {
              setPlaying(false);
              setRps(Number(e.target.value));
            }}
            onKeyDown={onKey}
          />
          <div className="presets">
            {PRESETS.map((preset) => (
              <button
                key={preset.id}
                type="button"
                className={rps === Number(lookup(preset.src)) ? "is-on" : ""}
                onClick={() => {
                  setPlaying(false);
                  setRps(Number(lookup(preset.src)));
                }}
              >
                {preset.label}
              </button>
            ))}
            <button type="button" className={playing ? "is-on" : ""} onClick={() => setPlaying((v) => !v)} disabled={reduced}>
              {playing ? "Pause" : "Play the run"}
            </button>
          </div>
        </div>

        <Curve rps={rps} />
        <Lanes busy={view.busy} queue={view.queue} shedding={view.shedding} limit={view.instrumentLimit} />
      </div>
    </section>
  );
}

function srcFor(op: { offered_rps: number }, field: string) {
  const index = ops().findIndex((item) => item.offered_rps === op.offered_rps);
  return `waves.${index}.ops.0.${field}`;
}

function Readout({ k, v, u }: { k: string; v: React.ReactNode; u: string }) {
  return (
    <div className="readout">
      <span>{k}</span>
      <strong>{v}</strong>
      <em>{u}</em>
    </div>
  );
}

function Curve({ rps }: { rps: number }) {
  const points = ops();
  const maxX = points[points.length - 1].offered_rps;
  const maxY = Math.max(...points.map((p) => p.p95_ms));
  const d = points
    .map((p, i) => {
      const x = 24 + (p.offered_rps / maxX) * 520;
      const y = 150 - (p.p95_ms / maxY) * 120;
      return `${i === 0 ? "M" : "L"} ${x} ${y}`;
    })
    .join(" ");
  const cx = 24 + (rps / maxX) * 520;
  const cy = 150 - (p95At(rps) / maxY) * 120;
  const pred = Number(lookup("prediction.capacity_rps"));
  const px = 24 + (pred / maxX) * 520;
  return (
    <svg className="curve" viewBox="0 0 560 180" role="img" aria-label="p95 against offered rate, recorded points">
      <text x="24" y="16" className="svg-label">p95 ms</text>
      <text x="430" y="172" className="svg-label">offered rps</text>
      <path d={d} fill="none" stroke="#c7ff70" strokeWidth="2" />
      {points.map((p) => (
        <circle key={p.offered_rps} cx={24 + (p.offered_rps / maxX) * 520} cy={150 - (p.p95_ms / maxY) * 120} r="3.5" fill="#f2f0e8" />
      ))}
      <line x1={px} y1="28" x2={px} y2="150" stroke="#b6a4f4" strokeDasharray="3 3" />
      <circle cx={cx} cy={cy} r="6" fill="#c7ff70" />
      <line x1="24" y1={150 - (Number(lookup("code.pool_timeout_s")) * 1000) / maxY * 120} x2="544" y2={150 - (Number(lookup("code.pool_timeout_s")) * 1000) / maxY * 120} stroke="#7ee7ff" strokeOpacity="0.7" />
    </svg>
  );
}

function Lanes({ busy, queue, shedding, limit }: { busy: number; queue: number; shedding: boolean; limit: boolean }) {
  const pool = Number(lookup("code.pool_size"));
  return (
    <div className="lanes" aria-hidden="true">
      {Array.from({ length: pool }, (_, i) => (
        <div key={i} className="lane">
          <i className={i < busy ? "hold" : ""} />
          {shedding && i === pool - 1 ? <b className="shatter" /> : null}
        </div>
      ))}
      <p>
        {queue > 0 ? "Queue at the pool" : "Lanes clear"}
        {limit ? " · instrument limit" : ""}
      </p>
    </div>
  );
}

function useReduced() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const apply = () => setReduced(mq.matches);
    apply();
    mq.addEventListener("change", apply);
    return () => mq.removeEventListener("change", apply);
  }, []);
  return reduced;
}

