declare module "*.css";

declare module "../lib/laneModel.mjs" {
  export function frame(offeredRps: number): {
    busy: number;
    queue: number;
    shedding: boolean;
    instrumentLimit: boolean;
    capacity: number;
    pool: number;
  };
}

input.contents:
import { useState } from "react";
import layout from "../data/graph-layout.json";
import steps from "../data/investigation.json";
import { Datum } from "./Datum";
import { useRun } from "../state/run";

const PRESSURE = new Set(["op", "handler", "branch", "acquire", "pool", "downstream", "compute"]);

const EDGES: { a: string; b: string; kind: "observed" | "inferred" }[] = [
  { a: "op", b: "handler", kind: "observed" },
  { a: "handler", b: "branch", kind: "inferred" },
  { a: "branch", b: "acquire", kind: "inferred" },
  { a: "acquire", b: "pool", kind: "inferred" },
  { a: "branch", b: "downstream", kind: "inferred" },
  { a: "downstream", b: "compute", kind: "inferred" },
];

export function Investigation() {
  const { selected, setSelected, confirmed, setConfirmed } = useRun();
  const [mode, setMode] = useState<"all" | "pressure">("all");
  const [step, setStep] = useState(0);
  const pos = Object.fromEntries(layout.nodes.map((n) => [n.id, n]));
  const current = steps.steps[step];

  function show(id: string) {
    if (mode === "pressure" && !PRESSURE.has(id)) return false;
    return true;
  }

  function scrub(index: number) {
    setStep(index);
    const lights = steps.steps[index]?.lights ?? [];
    if (lights[0]) setSelected(lights[0]);
  }

  return (
    <section id="graph" className="section graph-section">
      <div className="content">
        <p className="eyebrow">Recorded run · demo app · not your app</p>
        <h2>Code, then pressure, then the difference.</h2>
        <p className="lede centrepiece">
          The agent predicted about <Datum src="prediction.capacity_rps" /> rps from the code. The measured knee fell
          between <Datum src="knee.low_rps" /> and <Datum src="knee.high_rps" />.
        </p>
        <p className="principle">A plausible cause is not yet a proven one.</p>

        <div className="replay">
          <div className="phases" role="list">
            {["READ", "PREDICT", "LOAD", "EXPLAIN", "LIMITS"].map((phase) => (
              <span key={phase} className={current.phase === phase ? "is-on" : ""} role="listitem">
                {phase}
              </span>
            ))}
          </div>
          <label className="slider-label" htmlFor="replay">
            Replay
          </label>
          <input
            id="replay"
            type="range"
            min={0}
            max={steps.steps.length - 1}
            value={step}
            onChange={(e) => scrub(Number(e.target.value))}
          />
          <p className="replay-copy">
            {current.tool ? <code>{current.tool}</code> : null} {current.summary}
          </p>
          <button type="button" className="text-btn" onClick={() => setConfirmed(!confirmed)}>
            {confirmed ? "Show an unmet prediction" : "Show the recorded knee"}
          </button>
          {!confirmed && (
            <p className="miss">
              If the knee had landed elsewhere, this replay would say the prediction was unmet. The component does not
              assume the code was right.
            </p>
          )}
        </div>

        <div className="graph-layout">
          <div className="flatten" aria-hidden="true">
            <svg viewBox="0 0 1040 220" className="contour-bed">
              <path d="M0 180 C 200 170, 360 150, 520 40 S 900 20, 1040 16" fill="none" stroke="#c7ff70" strokeOpacity="0.35" />
              <path d="M0 190 C 200 182, 360 168, 520 70 S 900 48, 1040 40" fill="none" stroke="#c7ff70" strokeOpacity="0.18" />
            </svg>
          </div>
          <div className="graph-tools">
            <button type="button" className={mode === "all" ? "is-on" : ""} onClick={() => setMode("all")}>
              All relationships
            </button>
            <button type="button" className={mode === "pressure" ? "is-on" : ""} onClick={() => setMode("pressure")}>
              Pressure path
            </button>
          </div>
          <svg className="code-graph" viewBox="0 0 1040 420" role="img" aria-label="Widget route linked to the pool and the downstream call">
            {EDGES.map((edge) => {
              if (!show(edge.a) || !show(edge.b)) return null;
              const a = pos[edge.a];
              const b = pos[edge.b];
              const hot = selected === edge.a || selected === edge.b;
              return (
                <line
                  key={`${edge.a}-${edge.b}`}
                  x1={a.x}
                  y1={a.y}
                  x2={b.x}
                  y2={b.y}
                  className={`edge edge-${edge.kind}${hot ? " is-hot" : ""}`}
                />
              );
            })}
            {layout.nodes.map((node) => {
              if (!show(node.id)) return null;
              return (
                <NodeMark
                  key={node.id}
                  id={node.id}
                  x={node.x}
                  y={node.y}
                  active={selected === node.id || (current.lights as string[]).includes(node.id)}
                  onPick={() => setSelected(node.id)}
                />
              );
            })}
          </svg>
          <aside className="ledger" aria-label="Evidence ledger">
            <LedgerButton id="op" current={selected} onPick={setSelected} title="Knee under load">
              p95 moved between <Datum src="knee.low_rps" /> and <Datum src="knee.high_rps" /> rps. Observed under load.
            </LedgerButton>
            <LedgerButton id="pool" current={selected} onPick={setSelected} title="Pool">
              Size <Datum src="code.pool_size" />, timeout <Datum src="code.pool_timeout_s" /> s.{" "}
              <Datum src="code.evidence.pool" />. Inferred from code.
            </LedgerButton>
            <LedgerButton id="downstream" current={selected} onPick={setSelected} title="Downstream">
              <Datum src="code.downstream_ms.0" />–<Datum src="code.downstream_ms.1" /> ms.{" "}
              <Datum src="code.evidence.downstream" />. Inferred from code.
            </LedgerButton>
            <LedgerButton id="other" current={selected} onPick={setSelected} title="Not the same path">
              Under mixed load <Datum src="mixed.readyz_ms" /> ms on /readyz and <Datum src="mixed.healthz_ms" /> ms on
              /healthz. Other routes were not swept.
            </LedgerButton>
          </aside>
          <Inspector id={selected} confirmed={confirmed} />
        </div>
      </div>
    </section>
  );
}

function LedgerButton({
  id,
  current,
  onPick,
  title,
  children,
}: {
  id: string;
  current: string;
  onPick: (id: string) => void;
  title: string;
  children: React.ReactNode;
}) {
  return (
    <button type="button" className={current === id ? "is-on" : ""} onClick={() => onPick(id)}>
      <strong>{title}</strong>
      <span>{children}</span>
    </button>
  );
}

function NodeMark({
  id,
  x,
  y,
  active,
  onPick,
}: {
  id: string;
  x: number;
  y: number;
  active: boolean;
  onPick: () => void;
}) {
  const hatched = id === "other";
  return (
    <g className={`node${active ? " is-on" : ""}${hatched ? " is-hatched" : ""}`} transform={`translate(${x} ${y})`} onClick={onPick}>
      <Shape id={id} />
      <text y={id === "op" ? 36 : 28} textAnchor="middle" className="node-label">
        {label(id)}
      </text>
    </g>
  );
}

function Shape({ id }: { id: string }) {
  if (id === "op") return <rect x="-70" y="-16" width="140" height="32" rx="16" />;
  if (id === "pool") return <path d="M-16 -16 H10 L16 -8 V16 H-16 Z" />;
  if (id === "compute") return <polygon points="0,-18 16,-9 16,9 0,18 -16,9 -16,-9" />;
  if (id === "other") return <rect x="-18" y="-14" width="36" height="28" rx="4" />;
  return <circle r="14" />;
}

function label(id: string) {
  if (id === "op") return "GET /widgets/{id}";
  if (id === "handler") return "get_widget";
  if (id === "branch") return "_handle_buggy";
  if (id === "acquire") return "acquire_session";
  if (id === "pool") return "pool";
  if (id === "downstream") return "call_downstream";
  if (id === "compute") return "/compute";
  return "not tested";
}

function Inspector({ id, confirmed }: { id: string; confirmed: boolean }) {
  return (
    <div className="inspector" aria-live="polite">
      <p className="eyebrow">{label(id)}</p>
      {id === "op" && (
        <p>
          Observed under load. <Datum src="waves.0.ops.0.method" /> <Datum src="waves.0.ops.0.path" />.
        </p>
      )}
      {id === "handler" && (
        <p>
          Inferred from code. <Datum src="code.evidence.handler" />.
        </p>
      )}
      {id === "branch" && (
        <p>
          Inferred from code. <Datum src="code.evidence.branch" />.
        </p>
      )}
      {id === "acquire" && (
        <p>
          Inferred from code. <Datum src="code.evidence.acquire" />.
        </p>
      )}
      {id === "pool" && (
        <p>
          Inferred from code. Pool <Datum src="code.pool_size" /> at <Datum src="code.evidence.pool" />.
          {confirmed
            ? " The recorded knee sits near the estimate. That is not proof the pool is the only cause."
            : " This prediction is not treated as confirmed."}
        </p>
      )}
      {id === "downstream" && (
        <p>
          Inferred from code. <Datum src="code.evidence.downstream" />.
        </p>
      )}
      {id === "compute" && (
        <p>
          Inferred from code. <Datum src="code.evidence.compute" />.
        </p>
      )}
      {id === "other" && <p>Not tested on this sweep. Hatched so the gap stays visible in grayscale.</p>}
    </div>
  );
}

import { Datum } from "./Datum";

export function Problem() {
  return (
    <section id="problem" className="section">
      <div className="content split">
        <div>
          <h2>A slow chart is not a finding.</h2>
          <p className="lede">
            Load tests tell you latency climbed. They do not open the file. Loadline reads the code, predicts a
