import { useEffect, useState } from "react";
import { lookup, p95At } from "../lib/sample";

const TICKS = [
  ["hero", "Hero"],
  ["instrument", "Pressure"],
  ["problem", "Problem"],
  ["stages", "Stages"],
  ["graph", "Graph"],
  ["report", "Report"],
  ["safety", "Safety"],
  ["quickstart", "Start"],
] as const;

export function AscentRail() {
  const [progress, setProgress] = useState(0);
  const maxRps = Number(lookup("waves.3.ops.0.offered_rps"));
  const maxP = p95At(maxRps);
  let d = "";
  for (let i = 0; i <= 24; i += 1) {
    const t = i / 24;
    const x = 28 - (p95At(t * maxRps) / maxP) * 18;
    const y = 12 + t * 220;
    d += i === 0 ? `M ${x.toFixed(1)} ${y.toFixed(1)}` : ` L ${x.toFixed(1)} ${y.toFixed(1)}`;
  }
  const y = 12 + progress * 220;

  useEffect(() => {
    const onScroll = () => {
      const max = document.documentElement.scrollHeight - window.innerHeight;
      setProgress(max > 0 ? window.scrollY / max : 0);
    };
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <nav className="rail" aria-label="Section ascent">
      <svg viewBox="0 0 36 244" aria-hidden="true">
        <path d={d} fill="none" stroke="#c7ff70" strokeWidth="1.4" />
        <circle cx="16" cy={y} r="3.2" fill="#c7ff70" />
      </svg>
      <ol>
        {TICKS.map(([id, label]) => (
          <li key={id}>
            <a href={`#${id}`}>{label}</a>
          </li>
        ))}
      </ol>
    </nav>
  );
}

