  stroke: #f2f0e8;
  stroke-width: 1.4;
}

.node.is-on rect,
.node.is-on circle,
.node.is-on polygon,
.node.is-on path {
  stroke: #c7ff70;
  stroke-width: 2.2;
}

.node.is-hatched rect {
  fill: url(#none);
  stroke-dasharray: 2 2;
  opacity: 0.55;
}

.node-label {
