}

.sheet table {
  width: 100%;
  border-collapse: collapse;
  font-family: var(--font-mono);
  font-size: 13px;
}

.sheet th,
.sheet td {
  text-align: left;
  padding: 0.45rem 0.3rem;
  border-bottom: 1px solid rgba(28, 26, 20, 0.15);
}

.limits,
.checks {
  padding-left: 1.1rem;
}

.limits li + li,
.checks li + li {
  margin-top: 0.7rem;
}

.term {
  margin-top: 1rem;
  padding: 1rem 1.1rem;
  background: #070908;
  color: var(--hero-copy);
  border: 1px solid var(--void-line);
  overflow-x: auto;
  font-family: var(--font-mono);
  font-size: 12px;
  line-height: 1.7;
}

.compat td {
  vertical-align: top;
  width: 33%;
  padding-right: 1rem;
  color: var(--muted);
  line-height: 1.5;
}

.close {
  padding: 6rem 0 3rem;
  border-top: 1px solid var(--void-line);
}

.close h2 {
  max-width: 14ch;
  margin-bottom: 1.5rem;
}

.foot {
  margin-top: 3rem;
  display: grid;
  gap: 0.7rem;
}

.foot a {
  color: var(--signal);
}

.rail {
  position: fixed;
  right: 10px;
  top: 18vh;
  z-index: 30;
  width: 92px;
  color: var(--muted);
}

.rail svg {
  width: 36px;
  height: 220px;
}

.rail ol {
  list-style: none;
  margin: 0;
  padding: 0;
  font-family: var(--font-mono);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.rail a {
  color: var(--muted);
  text-decoration: none;
}

.narrow {
  max-width: 46rem;
}

@media (max-width: 980px) {
  .rail { display: none; }
  .split,
  .stages,
  .readouts,
  .graph-layout,
  .strip {
    grid-template-columns: 1fr;
  }
  .strip a + a { border-left: 0; border-top: 1px solid var(--void-line); }
  .world-span { display: flex; flex-direction: column; }
  .world-copy { display: contents; margin-top: 0; }
  .hero-copy { order: 1; min-height: auto; padding-top: calc(var(--nav-height) + 1.5rem); background: none; }
  .world-sticky { order: 2; position: relative; height: 52svh; }
  .strip { order: 3; }
  .instrument { order: 4; background: #070908; }
  h1 { max-width: none; }
}

@media (prefers-reduced-motion: reduce) {
  .contour-bed { animation: none; transform: none; }
}

