function ContourBed() {
  const maxRps = Number(lookup("waves.3.ops.0.offered_rps"));
  const maxP = p95At(maxRps);
  const path = (lift: number) => {
    let d = "";
    for (let i = 0; i <= 40; i += 1) {
      const t = i / 40;
      const x = t * 1120;
      const y = 180 - (p95At(t * maxRps) / maxP) * 140 + lift;
      d += i === 0 ? `M ${x.toFixed(1)} ${y.toFixed(1)}` : ` L ${x.toFixed(1)} ${y.toFixed(1)}`;
    }
    return d;
  };
  return (
    <div className="flatten" aria-hidden="true">
      <svg viewBox="0 0 1120 220" className="contour-bed">
        <path d={path(0)} fill="none" stroke="#c7ff70" strokeOpacity="0.45" />
        <path d={path(16)} fill="none" stroke="#c7ff70" strokeOpacity="0.18" />
      </svg>
    </div>
  );
}

