import { useEffect, useState } from "react";
import { BrandMark } from "./BrandMark";
import { REPO_URL } from "./repo";

const LINKS = [
  { href: "#how", label: "How it works" },
  { href: "#outcome", label: "Why Loadline" },
  { href: "#quickstart", label: "Quickstart" },
];

export function SiteNav() {
  const [open, setOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 12);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <header className={`nav${scrolled ? " nav-scrolled" : ""}`}>
      <div className="content nav-row">
        <BrandMark variant="light" />
        <nav className="nav-links" aria-label="Primary">
          {LINKS.map((l) => (
            <a key={l.href} href={l.href}>{l.label}</a>
          ))}
          <a href={REPO_URL} target="_blank" rel="noreferrer">GitHub</a>
        </nav>
        <a className="btn-solid nav-cta" href="#quickstart">Get started</a>
        <button type="button" className="nav-menu" aria-expanded={open} onClick={() => setOpen((v) => !v)}>
          Menu
        </button>
      </div>
      {open && (
        <div className="nav-mobile content">
          {LINKS.map((l) => (
            <a key={l.href} href={l.href} onClick={() => setOpen(false)}>{l.label}</a>
          ))}
          <a href="#quickstart" className="btn-solid" onClick={() => setOpen(false)}>Get started</a>
        </div>
      )}
    </header>
  );
}

import { CopyCodeButton } from "./CopyCodeButton";

const COMMANDS = `uv sync
cp .env.example .env
uv run loadline doctor
uv run loadline run --repo /absolute/path/to/your-app`;

export function Quickstart() {
  return (
    <section id="quickstart" className="section light">
      <div className="content narrow">
        <h2>Start from the repo</h2>
        <p className="lead">
          Install with <code>uv</code>, set your model key in <code>.env</code>, point at an app you can boot locally.
        </p>
        <CopyCodeButton code={COMMANDS} />
        <pre className="code-block">{COMMANDS}</pre>
        <p className="fine">
          Python 3.12 · Docker with Compose v2 · Git 2.36+. No PyPI package yet—clone NeatHacks and run from source.
        </p>
      </div>
    </section>
  );
}

export function SafetyBand() {
  return (
    <section id="safety" className="section">
      <div className="content narrow">
        <h2>Run it on your machine, on purpose</h2>
        <p className="lead dark">
          Loadline is for repos you can boot locally—not production traffic. Compose paths use a constrained network;
          that is not a promise of perfect isolation. Code you investigate is sent to the model provider you configure.
        </p>
      </div>
    </section>
  );
}

